 std::size_t k=0;for(auto i:packet_.active_rows)accum(pixel_factor(i),lambda[k++]);for(auto i:packet_.active_rows)for(int kind=0;kind<3;++kind)accum(domain_factor(i,kind),lambda[k++]);for(std::size_t i=0;i<physical_.size();++i)accum(physical_factor(i),lambda[k++]);for(std::size_t i=0;i<orders_.size();++i)accum(order_factor(i),lambda[k++]);k=0;for(auto i:packet_.active_rows)accum(rs_factor(i),nu[k++]);for(auto i:profile_rows_)for(int c=0;c<2;++c)accum(query_factor(i,c),nu[k++]);if(phase==Phase::kPrecision){if(!packet_.statistics_complete)throw std::runtime_error("missing complete W");for(const auto&g:packet_.groups)accum(statistical_factor(g),0.,true);}
 GradientReport out;out.state_token=s.token();out.scales_id=identity_.scales_id;out.complete_current_derivatives=true;for(std::size_t b=0;b<f.model.blocks.size();++b){const auto&p=f.model.blocks[b];for(std::size_t j=0;j<p.values.size();++j){const bool fixed=p.constant||std::find(p.fixed_indices.begin(),p.fixed_indices.end(),j)!=p.fixed_indices.end();out.scaled_projected_components.push_back(fixed?0.:projected_box_gradient(p.values[j],grad[b][j],p.scales[j],p.lower[j],p.upper[j]));}}
