     const int direction=right_room>=left_room?1:-1;const double room=direction>0?right_room:left_room,h0=std::min(nominal,.2*room);
     entry["nominal_h0"]=nominal;entry["h0"]=h0;entry["chart_bounds"]={chart_lo,chart_hi};entry["stencil_method"]="predeclared_roomier_legal_side_fourth_order";entry["one_sided_direction"]=direction;entry["central_cancellation_guard"]="minimum box/chart room < 1e-3 * nominal h0; no AD-dependent choice";
     struct RestoreOneSided{double* p;double x;~RestoreOneSided(){*p=x;}} restore{&p[b][c],x};
     std::vector<std::vector<double>> derivatives;eventio::Json estimates=eventio::Json::array();bool all_valid=h0>0.&&x+direction*h0/4!=x;
     for(double factor:{1.,.5,.25}){const double h=direction*h0*factor;std::array<std::vector<double>,5> values;for(auto&v:values)v.resize(nr);bool valid=true;
      for(int k=0;k<5;++k){p[b][c]=x+k*h;if(p[b][c]<lo||p[b][c]>hi||p[b][c]<chart_lo||p[b][c]>chart_hi||!f.cost->Evaluate(p.data(),values[k].data(),nullptr)){valid=false;break;}for(auto v:values[k])valid=valid&&std::isfinite(v);}
      p[b][c]=x;std::vector<double> derivative(nr,kInfinity);if(valid&&h!=0.)for(int q=0;q<nr;++q)derivative[q]=(-25*values[0][q]+48*values[1][q]-36*values[2][q]+16*values[3][q]-3*values[4][q])/(12*h);
      all_valid=all_valid&&valid;derivatives.push_back(derivative);estimates.push_back({{"signed_h",h},{"derivative",derivative},{"arithmetic_valid",valid}});
     }
     double self=0.,relative=0.;std::vector<double> ad(nr);for(int q=0;q<nr;++q){ad[q]=J[b][q*dims[b]+c];self=std::max(self,std::abs(derivatives[2][q]-derivatives[1][q])/(1+std::abs(derivatives[2][q])));relative=std::max(relative,std::abs(ad[q]-derivatives[2][q])/(1+std::abs(derivatives[2][q])));all_valid=all_valid&&std::isfinite(ad[q])&&std::isfinite(derivatives[2][q]);}
     const bool converged=all_valid&&self<tolerance,verified=converged&&relative<tolerance;entry["AD_derivative"]=ad;entry["one_sided_estimates"]=estimates;entry["all_stencils_arithmetic_valid"]=all_valid;entry["finite_difference_self_converged"]=converged;entry["relative_self_difference"]=self;entry["relative_error"]=relative;entry["verified"]=verified;entry["status"]=verified?"verified_fixed_finest_one_sided_fourth_order":!converged?"one_sided_finite_difference_not_self_converged":"AD_mismatch_after_one_sided_self_convergence";
